PI=math.pi
def T(en,ur=None,ps=None):return f'{en} || {ur or en} || {ps or en}'
def P(en,ur,ps):return f'p {T(en,ur,ps)}\n'
def EX(n,en,ur,ps):return f'example {n} | {T(en,ur,ps)}\n'
def S(w,h,aria,body):return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-label="{aria}"><title>{aria}</title>{body}</svg>'
tx=lambda x,y,t,sz=12,fill='#0f172a':f'<text x="{x}" y="{y}" font-size="{sz}" fill="{fill}" font-family="sans-serif">{t}</text>'
w,h=520,230
X=lambda v:250+v/(2.4*PI)*230
Y=lambda v:h/2-v*80
full=' '.join(f'{"M" if i==0 else "L"}{X(-1.2*PI+2.7*PI*i/200):.1f} {Y(math.cos(-1.2*PI+2.7*PI*i/200)):.1f}' for i in range(201))
bold=' '.join(f'{"M" if i==0 else "L"}{X(PI*i/80):.1f} {Y(math.cos(PI*i/80)):.1f}' for i in range(81))
lab=''.join(f'<path d="M{X(v):.1f} {Y(0)-4:.1f}v8" stroke="#334155"/>'+tx(X(v)-10,Y(0)+16,t,11) for v,t in [(-PI,'-π'),(-PI/2,'-π/2'),(PI/2,'π/2'),(PI,'π'),(3*PI/2,'3π/2'),(2*PI,'2π')])
f1237=S(w,h,'Figure 12.37: the graph of y = cos x with the part on [0, pi] in bold',f'<path d="M20 {Y(0):.1f}H{w-14}M{X(0):.1f} {h-8}V8" stroke="#334155" stroke-width="1.5" fill="none"/><path d="M{w-14} {Y(0):.1f}l-8-4v8Z" fill="#334155"/><path d="{full}" fill="none" stroke="#be185d" stroke-width="2"/><path d="{bold}" fill="none" stroke="#be185d" stroke-width="4.5"/>'+lab+tx(X(0)+6,Y(1)+4,'+1',11)+tx(X(0)+6,Y(-1)+4,'-1',11)+tx(w-24,Y(0)-6,'x',13)+tx(X(0)+6,16,'y',13))
w2,h2=240,260
