c=lambda v:130+v*70
d=lambda v:130-v*55
f1239=S(w2+60,h2+20,'Figure 12.39: the reflection y = Cos^-1 x of the graph of y = Cos x about the line y = x',f'<path d="M20 130H290M150 265V10" stroke="#334155" stroke-width="1.4" fill="none"/><path d="M40 230L270 20" stroke="#64748b" stroke-dasharray="5 4"/><path d="'+' '.join(f'{"M" if i==0 else "L"}{c(math.cos(PI*i/80)):.1f} {d(PI*i/80):.1f}' for i in range(81))+'" fill="none" stroke="#be185d" stroke-width="3.5"/>'+tx(180,36,'y = x',12)+tx(200,70,'y = Cos⁻¹x',12)+tx(c(1)-6,146,'+1',11)+tx(c(-1)-10,146,'-1',11)+tx(156,d(PI/2)+4,'π/2',11)+tx(156,d(PI)+4,'π',11)+tx(270,124,'x',12)+tx(156,16,'y',12))
tw,th=520,330
tX=lambda v:260+v/(2.5*PI)*230
